class Solution {
public:
    vector<int> relativeSortArray(vector<int>& arr1, vector<int>& arr2) {
        map<int, int> cnt;
        for (int x : arr1) cnt[x]++;
        vector<int> res;
        for (int x : arr2) {
            while (cnt[x]-- > 0) res.push_back(x);
            cnt.erase(x);
        }
        for (auto& [v, c] : cnt)
            while (c-- > 0) res.push_back(v);
        return res;
    }
};
